PAT=[(5,4),(4,4),(5,3),(3,4),(4,3),(3,3),(2,4),(3,2),(2,2),(4,None)]
def lvl(n): return "High" if n>=15 else "Medium" if n>=8 else "Low"
items=[]; lines={}
for li,(code,(full,evs)) in enumerate(L.items()):
    tops=[]
    for k,e in enumerate(evs):
        (eid,sub,fam,title,ev,mech,proc,sw,nw,meth,sb,vb,src,reg)=e
        S,V=PAT[k]
        if meth==ER and any(x in sb for x in ("Rumor","Speculation","Under discussion","more than 12 weeks")): S=min(S,2)  # rubric caps
        if "No PQD" in vb: V=None
        conf=["High","Medium","Medium","Low-Medium","Medium","Low-Medium","Low","Medium","Low","Low"][k]
        base={"id":f"{code.lower().replace(' ','-')}-{eid}","business_line":code,"sub_line":sub,"region":reg,"risk_family":fam,"confidence":conf,
          "shock_method":meth,"shock_basis":sb+" (simulated reading)","vulnerability_basis":vb if V is not None else "",
          "title":title,"summary_line":sw,"what_happened":ev+" (sample event).",
          "transmission":{"event":ev,"mechanism":mech,"dtcc_process":proc},"so_what":sw,"so_now_what":nw,
          "time_phased":{"now":"Watch this week's readings","next":"Re-score as new data arrives","later":"Revisit at next PQD release"},
          "why_this_line":f"Tagged {code} because it touches {proc[0].lower()+proc[1:]}.",
          "key_unknowns":["All readings on this card are simulated for the demo","Internal DTCC data not public"],
          "where_we_stand":"Sample card for layout and demo purposes.","shareable_line":title+".",
          "sources":src,"ai_generated_fields":["summary_line","so_what","so_now_what","shareable_line"],"review_status":"Simulated demo data"}
        # week 0 (latest) all items; week1 drop items 8,9 (new this week) and shift some scores; week2 also drop 7
        for w,(sid,_) in enumerate(SN):
            if w>=1 and k in (8,9): continue
            if w>=2 and k==7: continue
            s=S
            if w==1 and k in (0,3,5): s=max(1,S-1)
            if w==1 and k==2: s=min(5,S+1) if S<5 else S-2
            if w==2 and k in (0,1,3,5): s=max(1,S-1-(k==0))
            it=copy.deepcopy(base); it.update(snapshot=sid,shock=s,vulnerability=V,
               updated_at=f"{sid}T0{7+(k%2)}:{15+3*k:02d}:00-04:00")
            items.append(it)
            if w==0 and V: tops.append((s*V,title))
    tops.sort(reverse=True)
    hi=[t for n,t in tops if n>=15]
    lines[code]={"summary":{SN[0][0]:f"{len(hi)} High item{'s' if len(hi)!=1 else ''} this week. Top item: {tops[0][1]}. All readings are simulated for the demo.",
                            SN[1][0]:"Prior-week demo summary. Readings simulated.",SN[2][0]:"Earlier demo summary. Readings simulated."},
                 "review":[{"title":f"Unscored {full} headline awaiting analyst check","risk_family":"Strategic","reason":"no chain match yet (demo)","snapshot":SN[0][0]}]}
